*p1)*cos(p1)*p1^3 + 4*K*exp(3*p1 + p1)*exp(-3*p1 - 3*p1)*p1^3 - 4*K*exp(5*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^3 + 2*p1^6 + 4*K^2*exp(3*p1 + p1)*exp(-3*p1 - 3*p1) + 4*K^2*exp(5*p1 + 3*p1)*exp(-3*p1 - 3*p1) - 8*K^2))/(6*sin(p1)*cos(p1)*p1^6 - 12*K^2*sin(p1)*cos(p1) + 12*K^2*p1 - 3*exp(5*p1 + 3*p1)*exp(-3*p1 - 3*p1)*cos(p1)^2*p1^6 + 3*exp(p1 + 3*p1)*exp(-3*p1 - 3*p1)*cos(p1)^2*p1^6 + 6*K^2*exp(5*p1 + 3*p1)*exp(-3*p1 - 3*p1)*cos(p1)^2 - 6*K^2*exp(p1 + 3*p1)*exp(-3*p1 - 3*p1)*cos(p1)^2 - 2*K*exp(p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^4 - 2*K^2*exp(p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1 - 4*sin(p1)*exp(-3*p1 - 3*p1)*exp(3*p1 + 2*p1)*p1^7 - 6*sin(p1)*exp(-3*p1 - 3*p1)*exp(3*p1 + 2*p1)*p1^6 - 6*cos(p1)*exp(-3*p1 - 3*p1)*exp(3*p1 + 2*p1)*p1^6 + 6*cos(p1)*exp(4*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^6 + 4*sin(p1)*exp(4*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^7 - 6*sin(p1)*exp(4*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^6 + 8*K*cos(p1)*sin(p1)*p1^4 + 2*K*exp(5*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^4 - 2*K^2*exp(5*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1 - exp(5*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^7 - exp(p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^7 - 8*K^2*cos(p1)^2*p1 - 6*K^2*exp(5*p1 + 3*p1)*exp(-3*p1 - 3*p1) + 6*K^2*exp(p1 + 3*p1)*exp(-3*p1 - 3*p1) - 2*p1^7 + 24*K*sin(p1)*exp(4*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^3 + 6*K^2*cos(p1)*sin(p1)*exp(p1 + 3*p1)*exp(-3*p1 - 3*p1) + 3*cos(p1)*sin(p1)*exp(p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^6 - 4*K*sin(p1)*exp(-3*p1 - 3*p1)*exp(3*p1 + 2*p1)*p1^4 - 24*K*sin(p1)*exp(-3*p1 - 3*p1)*exp(3*p1 + 2*p1)*p1^3 + 4*K*cos(p1)*exp(-3*p1 - 3*p1)*exp(3*p1 + 2*p1)*p1^4 + 3*cos(p1)*sin(p1)*exp(5*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^6 + 6*K^2*cos(p1)*sin(p1)*exp(5*p1 + 3*p1)*exp(-3*p1 - 3*p1) - 4*K*cos(p1)*exp(4*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^4 - 4*K*sin(p1)*exp(4*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^4 - 12*K*cos(p1)*sin(p1)*exp(5*p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^3 + 12*K*cos(p1)*sin(p1)*exp(p1 + 3*p1)*exp(-3*p1 - 3*p1)*p1^3 + 4*cos(p1)^2*p1^7);

